// =====================================================
// PROCESS DATA: Scoring, Badges, Stats, Price Alerts
// =====================================================

const items = $input.all();
const gadgets = items.map(item => {
  const d = item.json;
  return {
    name: d['Gadget Name'] || 'Unknown',
    category: d['Category'] || 'Uncategorized',
    brand: d['Brand'] || '',
    price: parseFloat(d['Price (USD)']) || 0,
    targetPrice: parseFloat(d['Target Price (USD)']) || 0,
    store: d['Store / Source'] || '',
    url: d['Product URL'] || '',
    ram: parseFloat(d['RAM (GB)']) || 0,
    storage: parseFloat(d['Storage (GB)']) || 0,
    battery: parseFloat(d['Battery (mAh)']) || 0,
    display: parseFloat(d['Display Size (in)']) || 0,
    camera: parseFloat(d['Camera (MP)']) || 0,
    rating: parseFloat(d['Rating (out of 5)']) || 0,
    pros: (d['Pros'] || '').split(',').map(s => s.trim()).filter(Boolean),
    cons: (d['Cons'] || '').split(',').map(s => s.trim()).filter(Boolean),
    dateChecked: d['Date Checked'] || new Date().toISOString().split('T')[0]
  };
});

if (gadgets.length === 0) {
  return [{ json: { error: true, message: 'No gadget data found in Excel sheet.' } }];
}

// --- Normalize helper ---
function normalize(value, min, max) {
  if (max === min) return 0.5;
  return (value - min) / (max - min);
}

// --- Compute ranges for normalization ---
const prices = gadgets.map(g => g.price).filter(p => p > 0);
const ratings = gadgets.map(g => g.rating).filter(r => r > 0);
const rams = gadgets.map(g => g.ram).filter(r => r > 0);
const storages = gadgets.map(g => g.storage).filter(s => s > 0);
const batteries = gadgets.map(g => g.battery).filter(b => b > 0);
const cameras = gadgets.map(g => g.camera).filter(c => c > 0);

const range = (arr) => ({
  min: arr.length ? Math.min(...arr) : 0,
  max: arr.length ? Math.max(...arr) : 1
});

const priceRange = range(prices);
const ratingRange = range(ratings);
const ramRange = range(rams);
const storageRange = range(storages);
const batteryRange = range(batteries);
const cameraRange = range(cameras);

// --- Weighted scoring ---
gadgets.forEach(g => {
  const normPrice = g.price > 0 ? (1 - normalize(g.price, priceRange.min, priceRange.max)) : 0;
  const normRating = g.rating > 0 ? normalize(g.rating, ratingRange.min, ratingRange.max) : 0;

  // Spec score: average of available specs
  const specScores = [];
  if (g.ram > 0) specScores.push(normalize(g.ram, ramRange.min, ramRange.max));
  if (g.storage > 0) specScores.push(normalize(g.storage, storageRange.min, storageRange.max));
  if (g.camera > 0) specScores.push(normalize(g.camera, cameraRange.min, cameraRange.max));
  const normSpecs = specScores.length > 0 ? specScores.reduce((a, b) => a + b) / specScores.length : 0;

  const normBattery = g.battery > 0 ? normalize(g.battery, batteryRange.min, batteryRange.max) : 0;

  g.score = (normRating * 0.35) + (normPrice * 0.30) + (normSpecs * 0.20) + (normBattery * 0.15);
  g.score = Math.round(g.score * 100) / 100;
});

// --- Sort by score descending ---
gadgets.sort((a, b) => b.score - a.score);
gadgets.forEach((g, i) => g.rank = i + 1);

// --- Sort by price for price rank ---
const byPrice = [...gadgets].sort((a, b) => a.price - b.price);
byPrice.forEach((g, i) => g.priceRank = i + 1);

// --- Statistics ---
const avgPrice = prices.reduce((a, b) => a + b, 0) / prices.length;
const sortedPrices = [...prices].sort((a, b) => a - b);
const medianPrice = sortedPrices.length % 2 === 0
  ? (sortedPrices[sortedPrices.length / 2 - 1] + sortedPrices[sortedPrices.length / 2]) / 2
  : sortedPrices[Math.floor(sortedPrices.length / 2)];
const priceSpread = priceRange.max - priceRange.min;
const stdDev = Math.sqrt(prices.map(p => (p - avgPrice) ** 2).reduce((a, b) => a + b, 0) / prices.length);

// Percent above cheapest
gadgets.forEach(g => {
  g.percentAboveCheapest = priceRange.min > 0
    ? Math.round(((g.price - priceRange.min) / priceRange.min) * 100)
    : 0;
});

// --- Badge assignment ---
const badges = {};

// Best Overall: highest score
badges.bestOverall = gadgets[0];
gadgets[0].badges = gadgets[0].badges || [];
gadgets[0].badges.push('Best Overall');

// Best Value: highest score in bottom 40% by price
const priceCutoff = priceRange.min + (priceSpread * 0.4);
const valueCandidates = gadgets.filter(g => g.price <= priceCutoff);
if (valueCandidates.length > 0) {
  badges.bestValue = valueCandidates[0]; // already sorted by score
  valueCandidates[0].badges = valueCandidates[0].badges || [];
  valueCandidates[0].badges.push('Best Value');
}

// Best Camera: highest camera MP with rating >= 4.0
const cameraCandidates = gadgets.filter(g => g.camera > 0 && g.rating >= 4.0)
  .sort((a, b) => b.camera - a.camera);
if (cameraCandidates.length > 0) {
  badges.bestCamera = cameraCandidates[0];
  cameraCandidates[0].badges = cameraCandidates[0].badges || [];
  cameraCandidates[0].badges.push('Best Camera');
}

// Best Battery: highest battery mAh
const batteryCandidates = gadgets.filter(g => g.battery > 0).sort((a, b) => b.battery - a.battery);
if (batteryCandidates.length > 0) {
  badges.bestBattery = batteryCandidates[0];
  batteryCandidates[0].badges = batteryCandidates[0].badges || [];
  batteryCandidates[0].badges.push('Best Battery');
}

// Budget Pick: cheapest with rating >= 3.5
const budgetCandidates = gadgets.filter(g => g.rating >= 3.5).sort((a, b) => a.price - b.price);
if (budgetCandidates.length > 0) {
  badges.budgetPick = budgetCandidates[0];
  budgetCandidates[0].badges = budgetCandidates[0].badges || [];
  budgetCandidates[0].badges.push('Budget Pick');
}

// --- Price Alerts ---
const priceAlerts = gadgets.filter(g => g.targetPrice > 0 && g.price <= g.targetPrice);
priceAlerts.forEach(g => {
  g.priceAlertTriggered = true;
  g.savings = (g.targetPrice - g.price).toFixed(2);
  g.savingsPercent = ((g.targetPrice - g.price) / g.targetPrice * 100).toFixed(1);
});

// --- Group by category ---
const categories = {};
gadgets.forEach(g => {
  if (!categories[g.category]) categories[g.category] = [];
  categories[g.category].push(g);
});

const stats = {
  totalGadgets: gadgets.length,
  totalCategories: Object.keys(categories).length,
  avgPrice: avgPrice.toFixed(2),
  medianPrice: medianPrice.toFixed(2),
  minPrice: priceRange.min.toFixed(2),
  maxPrice: priceRange.max.toFixed(2),
  priceSpread: priceSpread.toFixed(2),
  stdDev: stdDev.toFixed(2)
};

return [{
  json: {
    gadgets,
    badges,
    priceAlerts,
    categories,
    stats
  }
}];

// =====================================================
// GENERATE HTML REPORT with SVG Charts
// =====================================================

const { gadgets, badges, priceAlerts, categories, stats } = $input.first().json;

if (!gadgets || gadgets.length === 0) {
  return [{ json: { htmlReport: '<html><body><h1>No data available</h1></body></html>' } }];
}

const currency = 'USD';
const currencySymbol = '$';
const reportTitle = 'Gadget Price Comparison Report';
const generatedDate = new Date().toISOString().split('T')[0];

// --- Helper: format price ---
function fmtPrice(p) { return currencySymbol + parseFloat(p).toFixed(2); }

// --- Build Stats Cards ---
const statsCards = `
  <div class="stat-card"><div class="stat-value">${stats.totalGadgets}</div><div class="stat-label">Total Gadgets</div></div>
  <div class="stat-card"><div class="stat-value">${fmtPrice(stats.avgPrice)}</div><div class="stat-label">Average Price</div></div>
  <div class="stat-card"><div class="stat-value">${fmtPrice(stats.medianPrice)}</div><div class="stat-label">Median Price</div></div>
  <div class="stat-card"><div class="stat-value">${fmtPrice(stats.minPrice)}</div><div class="stat-label">Lowest Price</div></div>
  <div class="stat-card"><div class="stat-value">${fmtPrice(stats.maxPrice)}</div><div class="stat-label">Highest Price</div></div>
  <div class="stat-card"><div class="stat-value">${fmtPrice(stats.priceSpread)}</div><div class="stat-label">Price Spread</div></div>
`;

// --- Build Winner Cards ---
const badgeConfig = [
  { key: 'bestOverall', cls: 'best-overall', icon: '\u{1F3C6}', title: 'Best Overall' },
  { key: 'bestValue', cls: 'best-value', icon: '\u{1F4B0}', title: 'Best Value' },
  { key: 'bestCamera', cls: 'best-camera', icon: '\u{1F4F7}', title: 'Best Camera' },
  { key: 'bestBattery', cls: 'best-battery', icon: '\u{1F50B}', title: 'Best Battery' },
  { key: 'budgetPick', cls: 'budget-pick', icon: '\u{1F3F7}', title: 'Budget Pick' }
];

let winnerCards = '';
badgeConfig.forEach(bc => {
  const g = badges[bc.key];
  if (g) {
    winnerCards += `
      <div class="winner-card ${bc.cls}">
        <div class="badge-icon">${bc.icon}</div>
        <div class="badge-title">${bc.title}</div>
        <div class="gadget-name">${g.name}</div>
        <div class="gadget-price">${fmtPrice(g.price)}</div>
      </div>`;
  }
});

// --- Build Comparison Tables (grouped by category) ---
let comparisonTables = '';
const badgeClassMap = {
  'Best Overall': 'badge-best-overall',
  'Best Value': 'badge-best-value',
  'Best Camera': 'badge-best-camera',
  'Best Battery': 'badge-best-battery',
  'Budget Pick': 'badge-budget'
};

Object.keys(categories).forEach(cat => {
  const catGadgets = categories[cat].sort((a, b) => a.price - b.price);
  comparisonTables += `<div class="category-label">${cat} (${catGadgets.length})</div>`;
  comparisonTables += `<table>
    <thead><tr>
      <th>#</th><th>Gadget</th><th>Price</th><th>Rating</th>
      <th>RAM</th><th>Storage</th><th>Battery</th><th>Camera</th>
      <th>Score</th><th>Store</th>
    </tr></thead><tbody>`;

  catGadgets.forEach((g, i) => {
    const rowClass = g.priceAlertTriggered ? 'price-alert-row' :
                     (g.badges && g.badges.includes('Best Value')) ? 'best-value-row' : '';
    let badgeHtml = '';
    if (g.badges) {
      g.badges.forEach(b => {
        badgeHtml += ` <span class="badge-inline ${badgeClassMap[b] || ''}">${b}</span>`;
      });
    }

    comparisonTables += `<tr class="${rowClass}">
      <td>${i + 1}</td>
      <td>${g.name}${badgeHtml}</td>
      <td>${fmtPrice(g.price)}</td>
      <td>${g.rating > 0 ? g.rating + '/5' : 'N/A'}</td>
      <td>${g.ram > 0 ? g.ram + 'GB' : '-'}</td>
      <td>${g.storage > 0 ? g.storage + 'GB' : '-'}</td>
      <td>${g.battery > 0 ? g.battery.toLocaleString() : '-'}</td>
      <td>${g.camera > 0 ? g.camera + 'MP' : '-'}</td>
      <td><span class="score-bar" style="width:${Math.round(g.score * 100)}px"></span> ${g.score}</td>
      <td>${g.store}</td>
    </tr>`;
  });
  comparisonTables += '</tbody></table>';
});

// --- Build SVG Bar Chart ---
const sortedByPrice = [...gadgets].sort((a, b) => b.price - a.price);
const maxPrice = Math.max(...gadgets.map(g => g.price));
const barHeight = 32;
const barGap = 8;
const chartWidth = 560;
const labelWidth = 180;
const chartHeight = sortedByPrice.length * (barHeight + barGap) + 20;

function priceColor(price) {
  const ratio = maxPrice > 0 ? price / maxPrice : 0;
  // Green (120) to Red (0) in HSL
  const hue = Math.round(120 * (1 - ratio));
  return `hsl(${hue}, 70%, 45%)`;
}

let barChartSvg = `<svg width="${labelWidth + chartWidth + 80}" height="${chartHeight}" xmlns="http://www.w3.org/2000/svg">`;
sortedByPrice.forEach((g, i) => {
  const y = i * (barHeight + barGap) + 10;
  const barW = maxPrice > 0 ? (g.price / maxPrice) * chartWidth : 0;
  const color = priceColor(g.price);
  barChartSvg += `
    <text x="${labelWidth - 8}" y="${y + barHeight / 2 + 4}" text-anchor="end" font-size="10" fill="#2c3e50" font-family="sans-serif">${g.name}</text>
    <rect x="${labelWidth}" y="${y}" width="${barW}" height="${barHeight}" rx="4" fill="${color}" opacity="0.85"/>
    <text x="${labelWidth + barW + 6}" y="${y + barHeight / 2 + 4}" font-size="10" fill="#2c3e50" font-weight="bold" font-family="sans-serif">${fmtPrice(g.price)}</text>`;
});
barChartSvg += '</svg>';

// --- Build SVG Radar Chart (Top 5 by score) ---
const top5 = gadgets.slice(0, Math.min(5, gadgets.length));
const radarSize = 380;
const radarCenter = radarSize / 2;
const radarRadius = 140;
const axes = ['Price (inv)', 'Rating', 'RAM', 'Storage', 'Battery'];
const numAxes = axes.length;
const radarColors = ['#e74c3c', '#3498db', '#27ae60', '#f5a623', '#9b59b6'];

// Normalize values for radar
function radarNorm(g) {
  const maxP = Math.max(...gadgets.map(x => x.price)) || 1;
  const maxR = Math.max(...gadgets.map(x => x.rating)) || 1;
  const maxRam = Math.max(...gadgets.map(x => x.ram)) || 1;
  const maxSt = Math.max(...gadgets.map(x => x.storage)) || 1;
  const maxBat = Math.max(...gadgets.map(x => x.battery)) || 1;
  return [
    1 - (g.price / maxP),  // inverted: cheaper = better
    g.rating / maxR,
    g.ram / maxRam,
    g.storage / maxSt,
    g.battery / maxBat
  ];
}

function polarToCart(cx, cy, r, angleIdx, total) {
  const angle = (Math.PI * 2 * angleIdx / total) - Math.PI / 2;
  return { x: cx + r * Math.cos(angle), y: cy + r * Math.sin(angle) };
}

let radarSvg = `<svg width="${radarSize + 200}" height="${radarSize + 60}" xmlns="http://www.w3.org/2000/svg">`;

// Grid rings
[0.25, 0.5, 0.75, 1.0].forEach(pct => {
  const r = radarRadius * pct;
  let points = '';
  for (let i = 0; i < numAxes; i++) {
    const p = polarToCart(radarCenter, radarCenter + 20, r, i, numAxes);
    points += `${p.x},${p.y} `;
  }
  radarSvg += `<polygon points="${points.trim()}" fill="none" stroke="#ddd" stroke-width="1"/>`;
});

// Axis lines + labels
for (let i = 0; i < numAxes; i++) {
  const p = polarToCart(radarCenter, radarCenter + 20, radarRadius, i, numAxes);
  const lp = polarToCart(radarCenter, radarCenter + 20, radarRadius + 18, i, numAxes);
  radarSvg += `<line x1="${radarCenter}" y1="${radarCenter + 20}" x2="${p.x}" y2="${p.y}" stroke="#ccc" stroke-width="1"/>`;
  radarSvg += `<text x="${lp.x}" y="${lp.y + 4}" text-anchor="middle" font-size="9" fill="#666" font-family="sans-serif">${axes[i]}</text>`;
}

// Gadget polygons
top5.forEach((g, gi) => {
  const vals = radarNorm(g);
  let points = '';
  vals.forEach((v, vi) => {
    const p = polarToCart(radarCenter, radarCenter + 20, radarRadius * v, vi, numAxes);
    points += `${p.x},${p.y} `;
  });
  radarSvg += `<polygon points="${points.trim()}" fill="${radarColors[gi]}" fill-opacity="0.15" stroke="${radarColors[gi]}" stroke-width="2"/>`;
});

// Legend
top5.forEach((g, gi) => {
  const lx = radarSize + 10;
  const ly = 30 + gi * 22;
  radarSvg += `<rect x="${lx}" y="${ly}" width="14" height="14" rx="3" fill="${radarColors[gi]}"/>`;
  radarSvg += `<text x="${lx + 20}" y="${ly + 11}" font-size="10" fill="#2c3e50" font-family="sans-serif">${g.name}</text>`;
});
radarSvg += '</svg>';

// --- Price Alerts Section ---
let alertsHtml = '';
if (priceAlerts && priceAlerts.length > 0) {
  alertsHtml = `<div class="alerts-section">
    <h2>\u{1F6A8} Price Alerts Triggered</h2>`;
  priceAlerts.forEach(g => {
    alertsHtml += `
      <div class="alert-card">
        <div>
          <div class="alert-gadget">${g.name}</div>
          <div class="alert-details">${g.store} | Target: ${fmtPrice(g.targetPrice)} | Current: ${fmtPrice(g.price)}</div>
        </div>
        <div class="alert-savings">Save ${fmtPrice(g.savings)} (${g.savingsPercent}%)</div>
      </div>`;
  });
  alertsHtml += '</div>';
}

// --- Gadget Detail Cards ---
let detailCards = '';
gadgets.forEach(g => {
  const prosHtml = g.pros.map(p => `<li>\u2705 <span>${p}</span></li>`).join('');
  const consHtml = g.cons.map(c => `<li>\u274C <span>${c}</span></li>`).join('');

  const specs = [];
  if (g.ram > 0) specs.push(`${g.ram}GB RAM`);
  if (g.storage > 0) specs.push(`${g.storage}GB Storage`);
  if (g.battery > 0) specs.push(`${g.battery.toLocaleString()}mAh`);
  if (g.display > 0) specs.push(`${g.display}" Display`);
  if (g.camera > 0) specs.push(`${g.camera}MP Camera`);

  const specsHtml = specs.map(s => `<span class="spec-chip">${s}</span>`).join('');
  let badgesHtml = '';
  if (g.badges) {
    g.badges.forEach(b => {
      badgesHtml += ` <span class="badge-inline ${badgeClassMap[b] || ''}">${b}</span>`;
    });
  }

  detailCards += `
    <div class="detail-card">
      <div class="detail-info">
        <div class="detail-name">${g.name}${badgesHtml}</div>
        <div class="detail-brand">${g.brand} | ${g.category} | ${g.store}</div>
        <div class="detail-specs">${specsHtml}</div>
        <div class="pros-cons">
          <div class="pros"><ul>${prosHtml}</ul></div>
          <div class="cons"><ul>${consHtml}</ul></div>
        </div>
      </div>
      <div class="detail-price-section">
        <div class="detail-price">${fmtPrice(g.price)}</div>
        <div class="detail-score-label">Score</div>
        <div class="detail-score-value">${g.score}</div>
        ${g.rating > 0 ? `<div class="detail-score-label">Rating</div><div class="detail-score-value">${g.rating}/5</div>` : ''}
      </div>
    </div>`;
});

// --- Assemble Full HTML ---
const html = `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <title>${reportTitle}</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }
    body { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif; font-size: 11pt; color: #2c3e50; line-height: 1.5; background: #fff; }
    @page { size: A4; margin: 15mm; }
    .page-break { page-break-before: always; }
    .report-header { background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%); color: #fff; padding: 30px 40px; border-radius: 12px; margin-bottom: 24px; }
    .report-header h1 { font-size: 26pt; font-weight: 700; margin-bottom: 8px; }
    .report-header .subtitle { font-size: 12pt; opacity: 0.85; }
    .report-header .meta { display: flex; gap: 24px; margin-top: 16px; font-size: 10pt; opacity: 0.75; }
    .stats-bar { display: flex; gap: 16px; margin-bottom: 24px; flex-wrap: wrap; }
    .stat-card { flex: 1; min-width: 120px; background: #f8f9fa; border-radius: 8px; padding: 16px; text-align: center; border: 1px solid #e9ecef; }
    .stat-card .stat-value { font-size: 20pt; font-weight: 700; color: #1a1a2e; }
    .stat-card .stat-label { font-size: 9pt; color: #6c757d; text-transform: uppercase; letter-spacing: 0.5px; }
    .winners-section { margin-bottom: 28px; }
    .winners-section h2 { font-size: 16pt; margin-bottom: 16px; color: #1a1a2e; border-bottom: 2px solid #e9ecef; padding-bottom: 8px; }
    .winner-cards { display: flex; gap: 14px; flex-wrap: wrap; }
    .winner-card { flex: 1; min-width: 150px; padding: 16px; border-radius: 10px; background: #fff; border: 2px solid #e9ecef; text-align: center; }
    .winner-card.best-overall { border-color: #f5a623; background: #fffdf5; }
    .winner-card.best-value { border-color: #27ae60; background: #f5fdf8; }
    .winner-card.best-camera { border-color: #3498db; background: #f5f9fd; }
    .winner-card.best-battery { border-color: #9b59b6; background: #faf5fd; }
    .winner-card.budget-pick { border-color: #e67e22; background: #fdf8f5; }
    .winner-card .badge-icon { font-size: 28pt; margin-bottom: 6px; }
    .winner-card .badge-title { font-size: 8pt; text-transform: uppercase; letter-spacing: 1px; font-weight: 600; color: #6c757d; }
    .winner-card .gadget-name { font-size: 11pt; font-weight: 700; margin: 6px 0; color: #1a1a2e; }
    .winner-card .gadget-price { font-size: 14pt; font-weight: 700; }
    .winner-card.best-overall .gadget-price { color: #f5a623; }
    .winner-card.best-value .gadget-price { color: #27ae60; }
    .winner-card.best-camera .gadget-price { color: #3498db; }
    .winner-card.best-battery .gadget-price { color: #9b59b6; }
    .winner-card.budget-pick .gadget-price { color: #e67e22; }
    .comparison-section { margin-bottom: 28px; }
    .comparison-section h2 { font-size: 16pt; margin-bottom: 16px; color: #1a1a2e; border-bottom: 2px solid #e9ecef; padding-bottom: 8px; }
    .category-label { font-size: 12pt; font-weight: 600; color: #0f3460; margin: 16px 0 8px 0; padding: 6px 12px; background: #e8edf2; border-radius: 6px; display: inline-block; }
    table { width: 100%; border-collapse: collapse; font-size: 9.5pt; margin-bottom: 16px; }
    thead th { background: #2c3e50; color: #fff; padding: 10px 8px; text-align: left; font-weight: 600; font-size: 8.5pt; text-transform: uppercase; letter-spacing: 0.5px; }
    thead th:first-child { border-radius: 6px 0 0 0; }
    thead th:last-child { border-radius: 0 6px 0 0; }
    tbody td { padding: 8px; border-bottom: 1px solid #e9ecef; }
    tbody tr:nth-child(even) { background: #f8f9fa; }
    .best-value-row { background: #e8f5e9 !important; }
    .price-alert-row { background: #fce4ec !important; }
    .badge-inline { display: inline-block; padding: 2px 6px; border-radius: 4px; font-size: 7.5pt; font-weight: 600; color: #fff; margin-left: 4px; vertical-align: middle; }
    .badge-best-overall { background: #f5a623; }
    .badge-best-value { background: #27ae60; }
    .badge-best-camera { background: #3498db; }
