// UPDATE PRICE HISTORY
// =====================================================

const fs = require('fs');
const path = '/data/gadgets/price-history.json';

let history = { runs: [] };

try {
  const raw = fs.readFileSync(path, 'utf8');
  history = JSON.parse(raw);
} catch (e) {
  // File doesn't exist yet, use empty history
}

const gadgets = $('Process & Score Data').first().json.gadgets;
const newRun = {
  date: new Date().toISOString(),
  gadgets: gadgets.map(g => ({
    name: g.name,
    price: g.price,
    store: g.store,
    score: g.score
  }))
};

history.runs.push(newRun);

// Keep only last 52 runs (1 year of weekly data)
if (history.runs.length > 52) {
  history.runs = history.runs.slice(-52);
}

fs.writeFileSync(path, JSON.stringify(history, null, 2));

return [{ json: { message: 'Price history updated', totalRuns: history.runs.length } }];
